function termPictogram(term){
 const motion=motionPictogram(term);if(motion){addChapterMotion(motion.querySelector('svg'),motion,term);return motion}
 const crop=pictograms[Number(term.id)];if(!crop)return null;
 const ns='http://www.w3.org/2000/svg';
 const frame=el('div','term-pictogram');
 const svg=document.createElementNS(ns,'svg');
 svg.setAttribute('viewBox',crop.rect.join(' '));
 svg.setAttribute('role','img');svg.setAttribute('aria-label',term.term+' 픽토그램');
 svg.setAttribute('preserveAspectRatio','xMidYMid meet');
 const picture=document.createElementNS(ns,'image');
 picture.setAttribute('href','/pictograms/'+crop.file);
 picture.setAttribute('width',crop.size[0]);picture.setAttribute('height',crop.size[1]);
 const clip=document.createElementNS(ns,'clipPath');clip.id='pictogram-clip-'+term.id;
 const rect=document.createElementNS(ns,'rect');['x','y','width','height'].forEach((key,i)=>rect.setAttribute(key,crop.rect[i]));clip.append(rect);
 picture.setAttribute('clip-path','url(#'+clip.id+')');svg.append(clip,picture);frame.append(svg);addChapterMotion(svg,frame,term);return frame;
}
let terms=[], active=null;
function el(tag,cls,text){const e=document.createElement(tag);e.className=cls;if(text!==undefined)e.textContent=text;return e}
function chapterFor(t){return chapters.find(c=>c.slug===t.categoryId)||chapters.find(c=>c.title===t.category)||chapters[0]}
function chapterTerms(c){return terms.filter(t=>chapterFor(t)===c)}
function renderHome(){
 $('categoryGrid').replaceChildren();
 chapters.forEach((c,i)=>{
  const list=chapterTerms(c);
  const a=el('a','chapter-card');a.href='#'+c.slug;
  a.append(el('span','chapter-index',String(i+1).padStart(2,'0')),el('h3','',c.title),el('p','',c.description));
  const bottom=el('div','chapter-meta');bottom.append(el('span','',list.length+'개 용어'),el('span','chapter-arrow','→'));a.append(bottom);$('categoryGrid').append(a);
 });
}
function renderTerms(){
 if(!active)return;
 clearChapterMotion();
 const q=$('search').value.trim().toLowerCase();
 const all=chapterTerms(active),list=all.filter(t=>(!q||(t.term+' '+t.definition).toLowerCase().includes(q)));
 $('count').textContent=list.length+'개 용어 / '+all.length+'개';
 $('grid').replaceChildren();
 if(!list.length){$('grid').append(el('div','empty',q?'검색어와 일치하는 용어가 없어요.':'아직 등록된 용어가 없어요.'));return}
 for(const t of list){
  const card=el('article','card'),top=el('div','cardtop');
  top.append(el('span','category',active.title));
  card.append(top,el('h2','',t.term));const pictogram=termPictogram(t);if(pictogram)card.append(pictogram);card.append(el('p','',t.definition));
  $('grid').append(card);
 }
}
function route(focus=false){
 active=chapters.find(c=>c.slug===location.hash.slice(1))||null;
 $('categoryHome').hidden=!!active;$('termPage').hidden=!active;
 if(active){$('search').value='';$('chapterTitle').textContent=active.title;$('chapterNumber').textContent='CHAPTER '+String(chapters.indexOf(active)+1).padStart(2,'0');$('chapterDescription').textContent=active.description;$('search').placeholder='이 분야의 용어 또는 정의 검색';document.title=active.title+' — AI·IT를 읽어드립니다';renderTerms();if(focus){$('termPage').scrollIntoView({block:'start'});$('chapterTitle').focus({preventScroll:true})}}
 else{document.title='AI·IT를 읽어드립니다';renderHome();if(focus){$('categoryHeading').setAttribute('tabindex','-1');$('categoryHeading').focus();$('categoryHome').scrollIntoView({block:'start'})}}
}
$('search').oninput=renderTerms;
window.addEventListener('hashchange',()=>route(true));
document.addEventListener('keydown',e=>{if(active&&e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('search').focus()}});
fetch('/api?op=terms').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{terms=data.terms;chapters=data.categories.map(c=>({...c,slug:c.id}));document.querySelectorAll('[data-category-count]').forEach(e=>e.textContent=chapters.length);route()}).catch(()=>{$('categoryGrid').replaceChildren(el('div','empty','용어를 불러오지 못했어요. 페이지를 새로고침해 주세요.'));$('grid').replaceChildren(el('div','empty','용어를 불러오지 못했어요. 페이지를 새로고침해 주세요.'))});
